const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileDirectionReacquisitionPresentation(input, reducedMotion = false) { const reacquire = clamp01(input.reacquire), pressure = clamp01(input.pressure), primary = Math.max(input.critical ? .9 : .74, .74 + .26 * reacquire - pressure * .04), stale = Math.max(.42, primary - (.24 + .16 * (1 - reacquire))); return { primaryDirectionScale: primary, staleDirectionScale: stale, tailLengthScale: Math.max(.68, .72 + .28 * reacquire) * (reducedMotion ? .94 : 1), presentationOnly: true }; }
export function impactDirectionReacquisitionPresentation(input, reducedFlash = false) { const reacquire = clamp01(input.reacquire), response = clamp01(input.responseStrength), pressure = clamp01(input.pressure), direction = Math.max(input.critical ? .82 : .72, .72 + response * .18 + reacquire * .1 - pressure * .04) * (reducedFlash ? .96 : 1), stale = Math.max(.4, direction - (.22 + .16 * (1 - reacquire))); return { directionAlphaScale: direction, responseScale: Math.max(direction, .76 + response * .2), staleDirectionScale: stale, presentationOnly: true }; }
export function hazardBoundaryDirectionReacquisitionPresentation(input, reducedFlash = false) { const reacquire = clamp01(input.reacquire), lane = clamp01(input.laneProximity), pressure = clamp01(input.pressure); return { edgeDirectionScale: input.telegraph ? Math.max(.9, .98 * (reducedFlash ? .98 : 1)) : .74 + .22 * reacquire, staleFillDirectionScale: Math.max(.5, 1 - (1 - reacquire) * (.28 + .12 * lane) - pressure * .08), presentationOnly: true }; }
export function safeLaneDirectionReacquisitionPresentation(input, reducedFlash = false) { const confidence = clamp01(input.confidence), reacquire = clamp01(input.reacquire), pressure = clamp01(input.pressure), hold = clamp01(pressure * (1 - reacquire)); return { pathAlphaFloor: input.visible ? Math.max(.93, .91 + confidence * .06) : 0, pathDirectionScale: input.visible ? 1 + hold * (.05 + .03 * confidence) * (reducedFlash ? .8 : 1) : 1, locatorScale: input.visible ? 1 + hold * .04 : 1, presentationOnly: true }; }
export function specialistFacingReacquisitionPresentation(input, reducedMotion = false) { const reacquire = clamp01(input.reacquire), pressure = clamp01(input.pressure), action = input.owner === 'special' ? 1 : input.owner === 'attack' ? .9 : input.owner === 'hit' ? .72 : input.owner === 'recovery' ? .5 : .2, facing = Math.max(input.critical ? .9 : .74, .76 + action * .16 + reacquire * .08 - pressure * .04), trail = Math.max(.46, facing - (.18 + .18 * (1 - reacquire))); return { facingScale: facing, trailDirectionScale: trail * (reducedMotion ? .94 : 1), presentationOnly: true }; }
export function directionReacquisitionBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), load = clamp01((input.projectileCount + input.impactCount + input.hazardCount * 1.35 + input.silhouetteCount) / 30), stress = clamp01(load * .82 + critical * .16); return { stress, canonicalScale: 1, primaryDirectionScale: 1, safeLaneScale: input.safeLaneVisible ? 1 + stress * .04 * (reducedFlash ? .8 : 1) : 1, staleDirectionScale: Math.max(.52, 1 - stress * .4) * (reducedMotion ? .96 : 1) * (reducedFlash ? .95 : 1), presentationOnly: true }; }
